tool_input.command:
mkdir -p /tmp/api-probe && cat > /tmp/api-probe/probe.mjs <<'EOF'
const root = process.argv[2];
const { handle } = await import(`${root}/src/api.js`);
const { reset, queryLog } = await import(`${root}/src/db.js`);
const { dueReminders } = await import(`${root}/src/scheduler.js`);
const create = (body) => handle({ method: 'POST', path: '/reminders', body });

// 1. double offset: IST user, 09:00 local = 03:30Z
reset();
const ist = create({ userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 330 }).body;
const fires = [];
for (let t = Date.parse('2026-02-28T18:00:00Z'); t <= Date.parse('2026-03-01T12:00:00Z'); t += 60_000) {
  if (dueReminders([ist], t).length) { fires.push(new Date(t).toISOString()); break; }
}
console.log('IST 09:00 (=03:30Z) first due at', fires[0]);
const ny = create({ userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: -300 }).body;
for (let t = Date.parse('2026-03-01T00:00:00Z'); ; t += 60_000) {
  if (dueReminders([ny], t).length) { console.log('NY 09:00 (=14:00Z) first due at', new Date(t).toISOString()); break; }
}

// 2. search with " and " in the term
reset();
create({ userId: 'u1', text: 'buy bread and butter', at: '2026-03-01T09:00' });
try { console.log('search "bread and butter":', handle({ method: 'GET', path: '/reminders/search', query: { userId: 'u1', q: 'bread and butter' } })); }
catch (e) { console.log('search "bread and butter" THREW:', e.message); }
try { console.log('search no q:', JSON.stringify(handle({ method: 'GET', path: '/reminders/search', query: { userId: 'u1' } }))); }
catch (e) { console.log('search no q THREW:', e.message); }
console.log('last sql:', queryLog.at(-1).sql);

// 3. bad `at` formats
reset();
for (const at of ['2026-03-01T09:00:00', '2026-03-01 09:00', 'tomorrow', '2026-03-01T09:00Z']) {
  const r = create({ userId: 'u1', text: 'x', at });
  console.log(JSON.stringify(at), '->', r.status, 'due_ms', r.body.due_ms);
}

// 4. delete another user's reminder
reset();
const other = create({ userId: 'victim', text: 'secret', at: '2026-03-01T09:00' }).body;
console.log('delete victim reminder w/o any user:', handle({ method: 'DELETE', path: `/reminders/${other.id}` }).status);

// 5. missing query object
try { handle({ method: 'GET', path: '/reminders' }); } catch (e) { console.log('GET /reminders no query THREW:', e.message); }
EOF
node /tmp/api-probe/probe.mjs "$PWD"

tool_input.content:
const root = process.argv[2];
const { handle } = await import(`${root}/src/api.js`);
const { reset, queryLog } = await import(`${root}/src/db.js`);
const { dueReminders } = await import(`${root}/src/scheduler.js`);
const create = (body) => handle({ method: 'POST', path: '/reminders', body });

const firstDue = (r, fromIso) => {
  for (let t = Date.parse(fromIso); t < Date.parse(fromIso) + 2 * 86400_000; t += 60_000) {
    if (dueReminders([r], t).length) return new Date(t).toISOString();
  }
};

// 1. double offset
reset();
const ist = create({ userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 330 }).body;
console.log('IST 09:00 (should be 03:30Z) first due at', firstDue(ist, '2026-02-28T12:00:00Z'));
const ny = create({ userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: -300 }).body;
console.log('NY 09:00 (should be 14:00Z) first due at', firstDue(ny, '2026-02-28T12:00:00Z'));

// 2. search with " and " in the term, and with no q
reset();
create({ userId: 'u1', text: 'buy bread and butter', at: '2026-03-01T09:00' });
try {
  console.log('search "bread and butter":', handle({ method: 'GET', path: '/reminders/search', query: { userId: 'u1', q: 'bread and butter' } }));
} catch (e) { console.log('search "bread and butter" THREW:', e.message); }
try {
  console.log('search no q:', JSON.stringify(handle({ method: 'GET', path: '/reminders/search', query: { userId: 'u1' } })));
} catch (e) { console.log('search no q THREW:', e.message); }
console.log('last sql:', queryLog.at(-1).sql);

// 3. bad `at` formats
reset();
for (const at of ['2026-03-01T09:00:00', '2026-03-01 09:00', 'tomorrow', '2026-03-01T09:00Z']) {
  const r = create({ userId: 'u1', text: 'x', at });
  console.log(JSON.stringify(at), '->', r.status, 'due_ms', r.body.due_ms);
}

// 4. delete another user's reminder
reset();
const other = create({ userId: 'victim', text: 'secret', at: '2026-03-01T09:00' }).body;
console.log('delete victim reminder, no user given:', handle({ method: 'DELETE', path: `/reminders/${other.id}` }).status);

// 5. missing query object
try { handle({ method: 'GET', path: '/reminders' }); } catch (e) { console.log('GET /reminders no query THREW:', e.message); }

